    "name": "buffer_add_to_queue",
    "description": "Add an item to a Buffer queue or send immediately.\n\nArgs:\n    organization_id: The Buffer organization ID.\n    channel_id: The channel ID to post to.\n    method: Share method (queue, schedule, share_next, share_now, draft, schedule_draft).\n    text: The post text content.\n    tags: Optional list of tag IDs.\n    scheduled_at: When to schedule the post (for schedule method).\n\nReturns:\n    JSON string with post details.",
    "parameters": {
      "properties": {
        "organization_id": {
          "description": "The Buffer organization ID.",
          "title": "Organization Id",
          "type": "string"
        },
        "channel_id": {
          "description": "The channel ID to post to.",
          "title": "Channel Id",
          "type": "string"
        },
        "method": {
          "default": "queue",
          "description": "Share method (queue, schedule, share_next, share_now, draft, schedule_draft).",
          "enum": [
            "queue",
            "schedule",
            "share_next",
            "share_now",
            "draft",
            "schedule_draft"
          ],
          "title": "Method",
          "type": "string"
        },
        "text": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "The post text content.",
          "title": "Text"
        },
        "tags": {
          "anyOf": [
            {
              "items": {
                "type": "string"
              },
              "type": "array"
            },
            {
              "type": "null"
            }
          ],
          "description": "Optional list of tag IDs.",
          "title": "Tags"
        },
        "scheduled_at": {
          "anyOf": [
            {
              "format": "date-time",
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "When to schedule the post (for schedule method).",
          "title": "Scheduled At"
        }
      },
      "required": [
        "organization_id",
        "channel_id",
        "method",
        "text",
        "tags",
        "scheduled_at"
      ],
      "title": "buffer_add_to_queue_args",
      "type": "object",
      "additionalProperties": false
    }
  },
